<main><section class="section"><div class="section__heading"><span>01</span><h2>Projects</h2></div><div class="card-grid"><?php foreach(projects(50) as $project): ?><article class="card" id="<?= e($project['slug']) ?>"><span class="card__meta"><?= e($project['category']) ?></span><h3><?= e($project['name']) ?></h3><p><?= e($project['summary']) ?></p><?php if($project['url']): ?><a href="<?= e($project['url']) ?>" target="_blank" rel="noopener">Open project →</a><?php endif; ?></article><?php endforeach; ?></div></section></main>